def solve(grid):
    rows = len(grid)
    cols = len(grid[0])

    color_cells = {}
    for r in range(rows):
        for c in range(cols):
            v = grid[r][c]
            if v != 0:
                color_cells.setdefault(v, set()).add((r, c))

    colors = list(color_cells.keys())
    if not colors:
        return [row[:] for row in grid]

    completed = {color: set(cells) for color, cells in color_cells.items()}

    for color in colors:
        cells = color_cells[color]
        if len(cells) < 3:
            continue
        cr = sum(r for r, c in cells) / len(cells)
        cc = sum(c for r, c in cells) / len(cells)

        any_sym = False
        for sym_type in ['h', 'v', 'r']:
            matches = total = 0
            for r, c in cells:
                if sym_type == 'h': rr, rc = round(2*cr - r), c
                elif sym_type == 'v': rr, rc = r, round(2*cc - c)
                else: rr, rc = round(2*cr - r), round(2*cc - c)
                if 0 <= rr < rows and 0 <= rc < cols:
                    total += 1
                    if (rr, rc) in cells: matches += 1
            if total > 0 and matches / total > 0.7:
                any_sym = True
                for r, c in list(cells):
                    if sym_type == 'h': rr, rc = round(2*cr - r), c
                    elif sym_type == 'v': rr, rc = r, round(2*cc - c)
                    else: rr, rc = round(2*cr - r), round(2*cc - c)
                    if 0 <= rr < rows and 0 <= rc < cols and grid[rr][rc] != 0:
                        completed[color].add((rr, rc))

        if not any_sym:
            min_r = min(r for r, c in cells)
            max_r = max(r for r, c in cells)
            min_c = min(c for r, c in cells)
            max_c = max(c for r, c in cells)
            bbox_area = (max_r - min_r + 1) * (max_c - min_c + 1)
            if bbox_area > 0 and len(cells) / bbox_area > 0.5:
                for r in range(min_r, max_r + 1):
                    for c in range(min_c, max_c + 1):
                        if grid[r][c] != 0:
                            completed[color].add((r, c))

    for color in colors:
        cells = color_cells[color]
        for r, c in cells:
            for dr, dc in [(0,1),(1,0),(1,1),(1,-1)]:
                nr, nc = r + dr, c + dc
                gap = []
                while 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] == 0: break
                    if grid[nr][nc] == color:
                        for gr, gc in gap: completed[color].add((gr, gc))
                        break
                    gap.append((nr, nc))
                    nr += dr; nc += dc

    cell_claims = {}
    for color in colors:
        for r, c in completed[color]:
            cell_claims.setdefault((r, c), set()).add(color)

    above = set()
    for (r, c), claims in cell_claims.items():
        if len(claims) >= 2:
            shown = grid[r][c]
            if shown in claims:
                for other in claims:
                    if other != shown:
                        above.add((shown, other))

    all_ordered = set()
    for a, b in above:
        all_ordered.add(a); all_ordered.add(b)

    order = []
    remaining = set(all_ordered)
    while remaining:
        tops = set(remaining)
        for a, b in above:
            if a in remaining and b in remaining: tops.discard(b)
        if not tops: tops = {min(remaining)}
        node = min(tops)
        order.append(node)
        remaining.discard(node)

    reversed_order = list(reversed(order))
    priority = {color: i for i, color in enumerate(reversed_order)}

    result = [row[:] for row in grid]
    for (r, c), claims in cell_claims.items():
        if len(claims) >= 2:
            overlapping = [cl for cl in claims if cl in priority]
            if overlapping:
                best = min(overlapping, key=lambda x: priority[x])
                result[r][c] = best

    return result

